import 'dart:typed_data';

/// Entity representing the multimodal result produced by Firebase AI / Google AI and photobooth.
class AiBadgeResult {
  /// The visually transformed image bytes (with AI generation or original photo).
  final Uint8List imageBytes;

  /// The fun title and vibe generated by Gemini Vision or fallback catalog.
  final String aiVibeTitle;

  /// Whether the badge image or title was genuinely produced by an AI model (vs deterministic fallback).
  final bool isAiTransformed;

  const AiBadgeResult({
    required this.imageBytes,
    required this.aiVibeTitle,
    this.isAiTransformed = false,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AiBadgeResult &&
          runtimeType == other.runtimeType &&
          aiVibeTitle == other.aiVibeTitle &&
          isAiTransformed == other.isAiTransformed &&
          _bytesEqual(imageBytes, other.imageBytes);

  @override
  int get hashCode =>
      aiVibeTitle.hashCode ^ imageBytes.length.hashCode ^ isAiTransformed.hashCode;

  static bool _bytesEqual(Uint8List a, Uint8List b) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
}
